mapper.insert:
	/* QnA 등록 */
    INSERT INTO inquiry (
        question_type_id      
        , title
        , question_content
        , user_id             
        , visible_yn          
        , answer_status       
        , created_at
    ) VALUES (
        #{qnaCategoryId}      
        , #{title}
        , #{content}
        , #{userId}
        , #{isVisible}
        , '답변대기'          
        , NOW()
    )

mapper.select:
/* QnA 상세 조회 (카테고리명, 답변 포함) */ SELECT /* 1. 문의 테이블 (inquiry) */ i.inquiry_id AS qnaId , i.question_type_id AS qnaCategoryId , i.title AS title , i.question_content AS content , i.answer_status AS status , i.visible_yn AS isVisible , i.created_at AS createdAt , i.user_id AS userId
/* 2. 코드 테이블 (code_item) - 카테고리명 */ , c.code_item_name AS categoryName
/* 3. 유저 테이블 (user) - 작성자 이름 */ , u.user_name AS userName
/* 4. 답변 테이블 (inquiry_answer) */ , ia.answer_content AS answerContent , ia.created_at AS answerCreatedAt
FROM inquiry i
/* 카테고리 정보 조회 */ LEFT JOIN code_item c ON i.question_type_id = c.code_item_id
/* 작성자 이름 조회 */ LEFT JOIN user u ON i.user_id = u.user_id
/* 답변 정보 조회 */ LEFT JOIN inquiry_answer ia ON i.inquiry_id = ia.inquiry_id
WHERE i.inquiry_id = #{qnaId}

mapper.update:
/* QnA 정보 수정 */ UPDATE inquiry
question_type_id = #{update.qnaCategoryId},
title = #{update.title},
question_content = #{update.content},
visible_yn = #{update.isVisible},
WHERE inquiry_id = #{qnaId}

mapper.delete:
/* 연결된 답변 삭제 */
DELETE FROM inquiry_answer
WHERE inquiry_id IN

    #{id}

/* 문의 삭제 (단건/다건 공용) */
DELETE FROM inquiry
WHERE inquiry_id IN

    #{id}
